(function(){var e=document.querySelector(".nav-toggle"),t=document.querySelector(".nav");!e||!t||(e.addEventListener("click",function(){var n=t.classList.toggle("open");e.setAttribute("aria-expanded",n?"true":"false")}),Array.prototype.forEach.call(t.querySelectorAll("a"),function(n){n.addEventListener("click",function(){t.classList.remove("open"),e.setAttribute("aria-expanded","false")})}))})();
